package com.englishhero.practice;

import java.util.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import tools.jackson.databind.ObjectMapper;
import com.englishhero.identity.SessionPrincipal;
import com.englishhero.reading.*;
import com.englishhero.web.BusinessException;
import static com.englishhero.practice.PracticePaperDtos.*;

@Service @Transactional(isolation=Isolation.READ_COMMITTED)
public class PracticePaperAdminService {
 private final PracticePaperMapper papers;private final PracticePaperContentService content;private final PracticeSetMapper sets;private final AdminArticleService admin;private final ObjectMapper json;private final org.springframework.jdbc.core.JdbcTemplate jdbc;
 public PracticePaperAdminService(PracticePaperMapper papers,PracticePaperContentService content,PracticeSetMapper sets,AdminArticleService admin,ObjectMapper json,org.springframework.jdbc.core.JdbcTemplate jdbc){this.papers=papers;this.content=content;this.sets=sets;this.admin=admin;this.json=json;this.jdbc=jdbc;}
 private AdminInput normalize(AdminInput d,boolean available){if(d==null||d.components()==null)throw BusinessException.invalid("components","请选择七个组成");var descriptors=d.components().stream().map(c->{if(c==null)throw BusinessException.invalid("components","组成不能为空");return content.descriptor(c,false);}).toList();if(available){descriptors.stream().map(c->content.version(c.setVersionId()).setId()).distinct().sorted().forEach(id->sets.get(id,true));descriptors=d.components().stream().map(c->content.descriptor(c,true)).toList();}var sorted=PracticePaperRules.validateComponents(d.examCode(),d.year(),d.month(),descriptors);return new AdminInput(null,PracticePaperRules.title(d.title()),"CET4",d.year(),d.month(),PracticePaperRules.source(d.sourceNote()),sorted.stream().map(c->new ComponentInput(c.slot(),c.setVersionId())).toList());}
 private PracticePaperMapper.Paper locked(String id,Integer expected){var p=papers.paper(ArticleRules.id(id,"paperId"),true);PracticeAdminService.lock(expected,p.lock());return p;}
 public PaperView create(SessionPrincipal actor,AdminInput d){admin.requireAdmin(actor);var value=normalize(d,true);long id=papers.insert("INSERT INTO practice_paper(draft_json,created_by,updated_by) VALUES(?,?,?)",json.writeValueAsString(value),actor.userId(),actor.userId());return view(papers.paper(id,false));}
 public PaperView save(SessionPrincipal actor,String id,AdminInput d){admin.requireAdmin(actor);if(d==null)throw BusinessException.invalid("paper","请填写组卷信息");var p=locked(id,d.expectedLockVersion());var value=normalize(d,true);papers.draft(p,value,actor.userId());return view(papers.paper(p.id(),false));}
 public PaperView get(SessionPrincipal actor,String id){admin.requireAdmin(actor);return view(papers.paper(ArticleRules.id(id,"paperId"),false));}
 public List<ComponentAttempt> preview(SessionPrincipal actor,String id){admin.requireAdmin(actor);var p=papers.paper(ArticleRules.id(id,"paperId"),false);return p.draft().components().stream().map(c->content.component(c,new ResponseInput(c.slot(),"",Map.of()),true,java.time.Instant.now(),java.time.Instant.now())).toList();}
 public List<PaperView> list(SessionPrincipal actor){admin.requireAdmin(actor);return papers.papers().stream().map(this::view).toList();}
 public PaperView review(SessionPrincipal actor,String id,LockInput d){admin.requireAdmin(actor);var p=locked(id,d==null?null:d.expectedLockVersion());normalize(p.draft(),true);papers.review(p,actor.userId());return view(papers.paper(p.id(),false));}
 public PaperView publish(SessionPrincipal actor,String id,LockInput d){admin.requireAdmin(actor);var p=locked(id,d==null?null:d.expectedLockVersion());if(!p.reviewed())throw new BusinessException(400,"PRACTICE_REVIEW_REQUIRED","请先确认整卷组成与来源");var value=normalize(p.draft(),true);long v=papers.insert("INSERT INTO practice_paper_version(paper_id,version_no,metadata_json,created_by) VALUES(?,?,?,?)",p.id(),p.revision()+1,json.writeValueAsString(value),actor.userId());int n=0;for(var c:value.components())jdbc.update("INSERT INTO practice_paper_component(paper_version_id,slot,set_version_id,sort_order) VALUES(?,?,?,?)",v,c.slot(),ArticleRules.id(c.setVersionId(),"setVersionId"),n++);papers.publish(p,v,actor.userId());return view(papers.paper(p.id(),false));}
 public PaperView unpublish(SessionPrincipal actor,String id,LockInput d){admin.requireAdmin(actor);var p=locked(id,d==null?null:d.expectedLockVersion());if(p.published()==null)throw PracticeAdminService.missing();papers.unpublish(p,actor.userId());return view(papers.paper(p.id(),false));}
 public List<PaperView> versions(SessionPrincipal actor,String id){admin.requireAdmin(actor);long pid=ArticleRules.id(id,"paperId");papers.paper(pid,false);return papers.versions(pid).stream().map(v->new PaperView(""+pid,""+v.id(),v.metadata().title(),"CET4",v.metadata().year(),v.metadata().month(),v.metadata().sourceNote(),"PUBLISHED",v.revision(),0,true,v.metadata().components(),content.details(v.metadata().components()),List.of(),true,null,null)).toList();}
 private PaperView view(PracticePaperMapper.Paper p){var d=p.draft();String unavailable=content.unavailable(d.components());return new PaperView(""+p.id(),p.published()==null?null:""+p.published(),d.title(),d.examCode(),d.year(),d.month(),d.sourceNote(),p.status(),p.revision(),p.lock(),p.reviewed(),d.components(),content.details(d.components()),p.reviewed()?List.of():List.of("尚未确认整卷组成与来源"),unavailable==null,unavailable,null);}
 public List<Candidate> candidates(SessionPrincipal actor,PaperQuery q){admin.requireAdmin(actor);return jdbc.query("SELECT v.id FROM practice_set s JOIN practice_set_version v ON v.id=s.published_version_id WHERE s.status='PUBLISHED' AND s.exam_code='CET4' ORDER BY s.id",(r,n)->content.version(r.getString(1))).stream().filter(v->{var m=content.metadata(v);return "PAST".equals(m.sourceKind())&&(q.year()==null||q.year().equals(m.year()))&&(q.month()==null||q.month().equals(m.month()))&&("CET4".equals(q.exam()));}).map(v->{var m=content.metadata(v);return new Candidate(""+v.setId(),""+v.id(),m.titleZh().isBlank()?m.title():m.titleZh(),v.readingType(),PracticeSubjectiveRules.isSubjective(v.readingType())?1:content.questions(v).size(),v.revision(),m.year(),m.month(),m.sourceName()+" · "+m.usageNote());}).toList();}
}
